    s2_1Title: "2.1 User Eligibility",
    s2_1P1:
      "You confirm that, when you complete the registration process or otherwise actually use this service in a manner permitted by Luyun Technology, you shall be a natural person, legal person, or other organization with full civil capacity for rights and full capacity for civil conduct.",
    s2_1P2:
      "If you are a minor or a person with limited capacity for civil conduct, you do not have the aforementioned eligibility, and you and your guardian shall bear all consequences arising from your improper registration.",
    s2_2Title: "2.2 Account Registration",
    s2_2P1:
      "After you fill in information as prompted on the registration page, read and agree to this Agreement, and complete the entire registration process, you will obtain a NexusClaw platform account and become a NexusClaw platform user.",
    s2_2P2:
      "You understand and promise that the account you set up must not violate national laws and regulations or Luyun Technology's relevant rules, and your account name, avatar, bio, and other registration information or personal information must not contain unlawful or inappropriate content.",
    s2_3Title: "2.3 Account Security",
    s2_3P1:
      "Your account is set up and kept by you. Luyun Technology will never proactively ask you to provide your account password.",
    s2_3P2:
      "You shall be responsible for the outcome of all activities under your account (including but not limited to online signing of agreements, publishing information, purchasing goods and services, and disclosing information).",
    s2_3P3:
      "Luyun Technology is not liable for losses and consequences caused by your voluntary disclosure or by attacks, fraud, or similar acts by others; you should seek recovery from the infringing party through judicial, administrative, or other remedies.",
    s2_4Title: "2.4 Account Deactivation",
    s2_4P1:
      "You have the right to apply to deactivate your account through system settings or by contacting customer support. Once deactivated, you will no longer be able to use that account, and you will not be able to retrieve any content or information in or related to that account.",
    s3Title: "3. Protection of Users' Personal Information",
    s3P1: "Protecting users' personal information is a fundamental principle of Luyun Technology. Luyun Technology will collect, use, store, and share your personal information in accordance with this Agreement and the Privacy Policy.",
    s3P2: "For matters relating to personal information protection not expressly provided for in this Agreement, the content of the Privacy Policy shall prevail.",
    s4Title: "4. Code of Conduct for Users",
    s4_1Title: "4.1 Content Standards",
    s4_1P1:
      "When using this service, you must not use it to engage in any of the following:",
    s4_1Item1:
      "Publishing, transmitting, disseminating, or storing content that violates national laws and regulations",
    s4_1Item2:
      "Publishing, transmitting, disseminating, or storing content that infringes on others' reputation, likeness, intellectual property, trade secrets, or other lawful rights",
    s4_1Item3:
      "Fabricating facts or concealing the truth to mislead or deceive others",
    s4_1Item4:
      "Publishing, transmitting, or disseminating advertisements or spam",
    s4_1Item5:
      "Engaging in other conduct that violates laws, regulations, policies, public order, good morals, or social ethics",
    s4_2Title: "4.2 Software Use Standards",
    s4_2P1:
      "Unless permitted by law or authorized in writing by Luyun Technology, you must not engage in any of the following while using this service:",
    s4_2Item1: "Removing copyright information from the software or its copies",
